#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
部署脚本 - 在服务器上运行此脚本即可更新所有文件
用法: python3 deploy_fix.py
"""
import base64, zlib, os

# ========== display.html (压缩base64) ==========
DISPLAY_B64 = ""

# ========== app.py (压缩base64) ==========
APP_B64 = ""

CONTEST_DIR = '/www/wwwroot/contest'

# 写入 display.html
print('正在更新 display.html ...')
display_data = zlib.decompress(base64.b64decode(DISPLAY_B64))
display_path = os.path.join(CONTEST_DIR, 'templates', 'display.html')
os.makedirs(os.path.dirname(display_path), exist_ok=True)
with open(display_path, 'wb') as f:
    f.write(display_data)
print(f'  已写入 {len(display_data)} 字节 -> {display_path}')

# 写入 app.py
print('正在更新 app.py ...')
app_data = zlib.decompress(base64.b64decode(APP_B64))
app_path = os.path.join(CONTEST_DIR, 'app.py')
with open(app_path, 'wb') as f:
    f.write(app_data)
print(f'  已写入 {len(app_data)} 字节 -> {app_path}')

# 修复 state.json 中的负分
state_path = os.path.join(CONTEST_DIR, 'state.json')
if os.path.exists(state_path):
    import json
    with open(state_path, 'r', encoding='utf-8') as f:
        s = json.load(f)
    fixed = 0
    for c in s.get('companies', []):
        if c.get('score', 0) < 0:
            c['score'] = 0
            fixed += 1
    if fixed > 0:
        with open(state_path, 'w', encoding='utf-8') as f:
            json.dump(s, f, ensure_ascii=False, indent=2)
        print(f'  修复了 {fixed} 个负分')
    else:
        print('  state.json 无负分，无需修复')

print()
print('=' * 50)
print('  所有文件已更新！')
print('  请重启应用:')
print('    kill $(pgrep -f "python3 app.py") 2>/dev/null')
print('    cd /www/wwwroot/contest')
print('    nohup python3 app.py > contest.log 2>&1 &')
print('=' * 50)
